    class ProxySubject {
        -_real RealSubject
        -_cache Map
        +request() string
        -_checkAccess() bool
        -_logCall() void
    }
    class Client {
        -subject Subject
        +run() void
    }
    Subject <|.. RealSubject : implements
    Subject <|.. ProxySubject : implements
    ProxySubject o-- RealSubject : controls
    Client --> Subject : depends on

