// ── Virtual Proxy: lazy image loading ────────────────────────────
class RealImage {
  constructor(filename) {
    this.filename = filename;
    this._load(); // expensive I/O — called only once
  }
  _load() {
    console.log(`[RealImage] Loading '${this.filename}' from disk...`);
    this.data = `<binary data: ${this.filename}>`; // simulate disk read
  }
  display()  { console.log(`[RealImage] Rendering '${this.filename}'`); }
  getSize()  { return 2048; } // bytes
}

class ImageProxy {
  constructor(filename) {
    this.filename = filename;
    this._real = null;       // NOT loaded yet — zero cost at construction
  }
  _ensureLoaded() {
    if (!this._real) {
      this._real = new RealImage(this.filename); // lazy init — first access only
    }
    return this._real;
  }
  display() { this._ensureLoaded().display(); }       // triggers load if needed
  getSize() { return this._real ? this._real.getSize() : 0; } // answers cheaply
}

const hero = new ImageProxy('hero-banner.png');
console.log('Size before display:', hero.getSize());  // 0  — not loaded yet
hero.display();  // [RealImage] Loading 'hero-banner.png'... then Rendering
hero.display();  // [RealImage] Rendering  — NO second load
console.log('Size after display:', hero.getSize());   // 2048

console.log('');

// ── Protection Proxy: permission-based access ─────────────────────
class DocumentService {
  getDocument(id)    { return `Content of doc #${id}`; }
  deleteDocument(id) { console.log(`[DocService] Deleted doc #${id}`); }
  publishDocument(id){ console.log(`[DocService] Published doc #${id}`); }
}

class SecureDocumentProxy {
  constructor(user) {
    this._service = new DocumentService();
    this._user    = user;
  }
  _require(permission) {
    if (!this._user.roles.includes(permission)) {
      throw new Error(`Forbidden: '${permission}' required for user '${this._user.name}'`);
    }
  }
  getDocument(id)    { this._require('read');    return this._service.getDocument(id); }
  deleteDocument(id) { this._require('admin');   this._service.deleteDocument(id); }
  publishDocument(id){ this._require('editor');  this._service.publishDocument(id); }
}

const reader = { name: 'Alice', roles: ['read'] };
const editor = { name: 'Bob',   roles: ['read', 'editor'] };
const admin  = { name: 'Carol', roles: ['read', 'editor', 'admin'] };

const aliceProxy = new SecureDocumentProxy(reader);
console.log(aliceProxy.getDocument(1));         // Content of doc #1
try { aliceProxy.publishDocument(1); } catch(e) { console.log(e.message); }
// Forbidden: 'editor' required for user 'Alice'

const bobProxy = new SecureDocumentProxy(editor);
bobProxy.publishDocument(1);  // [DocService] Published doc #1
try { bobProxy.deleteDocument(1); } catch(e) { console.log(e.message); }
// Forbidden: 'admin' required for user 'Bob'

const carolProxy = new SecureDocumentProxy(admin);
carolProxy.deleteDocument(1); // [DocService] Deleted doc #1

console.log('');

// ── Caching Proxy: avoid re-running expensive operations ──────────
class WeatherService {
  fetchForecast(city) {
    console.log(`[WeatherService] Fetching live forecast for '${city}'...`);
    return { city, temp: 22, condition: 'Sunny', ts: Date.now() };
  }
}

class CachingWeatherProxy {
  constructor(ttlMs = 60_000) {
    this._service = new WeatherService();
    this._cache   = new Map(); // key -> { data, expiresAt }
    this._ttlMs   = ttlMs;
  }
  fetchForecast(city) {
    const cached = this._cache.get(city);
    if (cached && Date.now() < cached.expiresAt) {
      console.log(`[Cache] HIT for '${city}'`);
      return cached.data;
    }
    const data = this._service.fetchForecast(city);
    this._cache.set(city, { data, expiresAt: Date.now() + this._ttlMs });
    console.log(`[Cache] MISS — stored '${city}' (TTL ${this._ttlMs}ms)`);
    return data;
  }
}

const weather = new CachingWeatherProxy(5_000);
console.log(weather.fetchForecast('Tokyo'));   // MISS — hits WeatherService
console.log(weather.fetchForecast('Tokyo'));   // HIT  — returned from cache
console.log(weather.fetchForecast('Paris'));   // MISS — different key

// ── ES6 Proxy: validation + logging + Vue-style reactivity ───────

// 1. Validation Proxy — reject bad data at the property level
function createValidated(schema) {
  const target = {};
  return new Proxy(target, {
    set(obj, prop, value) {
      const validator = schema[prop];
      if (validator && !validator(value)) {
        throw new TypeError(`Invalid value for '${prop}': ${JSON.stringify(value)}`);
      }
      obj[prop] = value;
      return true; // must return true to signal success
    },
    get(obj, prop) {
      if (prop in obj) return obj[prop];
      return undefined;
    },
  });
}

const config = createValidated({
  port:    v => Number.isInteger(v) && v > 0 && v < 65536,
  timeout: v => Number.isFinite(v) && v > 0,
  host:    v => typeof v === 'string' && v.length > 0,
});

config.port    = 3000;         // OK
config.host    = 'localhost';  // OK
config.timeout = 5000;         // OK
console.log(config.port, config.host, config.timeout); // 3000 localhost 5000
try { config.port = 99999; } catch(e) { console.log(e.message); }
// Invalid value for 'port': 99999
try { config.port = 'three thousand'; } catch(e) { console.log(e.message); }
// Invalid value for 'port': "three thousand"

console.log('');

// 2. Revocable Proxy — grant and then permanently revoke access
const data = { secret: 'API_KEY_XYZ' };
const { proxy: secureProxy, revoke } = Proxy.revocable(data, {
  get(target, prop) {
    console.log(`[RevocableProxy] Reading '${prop}'`);
    return target[prop];
  },
});

console.log(secureProxy.secret); // [RevocableProxy] Reading 'secret'  →  API_KEY_XYZ
revoke();                        // permanently revoke the capability
try { console.log(secureProxy.secret); } catch(e) { console.log('Revoked:', e.message); }
// Revoked: Cannot perform 'get' on a proxy that has been revoked

console.log('');

// 3. Mini Vue-style reactivity — track reads, notify on writes
function reactive(state) {
  const effects = new Map(); // prop -> Set of effect callbacks
  let currentEffect = null;

  function watchEffect(fn) {
    currentEffect = fn;
    fn(); // run once to collect dependencies
    currentEffect = null;
  }

  const proxy = new Proxy(state, {
    get(target, prop) {
      if (currentEffect) {
        if (!effects.has(prop)) effects.set(prop, new Set());
        effects.get(prop).add(currentEffect); // track dependency
      }
      return target[prop];
    },
    set(target, prop, value) {
      target[prop] = value;
      if (effects.has(prop)) {
        effects.get(prop).forEach(fn => fn()); // trigger dependent effects
      }
      return true;
    },
  });

  return { proxy, watchEffect };
}

const { proxy: appState, watchEffect } = reactive({ count: 0, name: 'World' });

watchEffect(() => {
  console.log(`[Effect] Hello, ${appState.name}! Count: ${appState.count}`);
});
// [Effect] Hello, World! Count: 0  (runs immediately to register deps)

appState.count++;   // [Effect] Hello, World! Count: 1
appState.name = 'Vue';  // [Effect] Hello, Vue! Count: 1
appState.count = 5;     // [Effect] Hello, Vue! Count: 5
